-- view_company_users_companies por empresa (um registro por usuario membro e empresa; escopo "column").
-- Rollback: recriar a view a partir de 202610061724_replace_view.sql.
CREATE OR REPLACE VIEW `view_company_users_companies` AS select `um`.`id` AS `id`,`cmx`.`company_id` AS `company_id`,`um`.`username` AS `um_username`,`um`.`status` AS `um_status`,`uc`.`name` AS `uc_name`,`uc`.`email` AS `uc_email`,(select count(0) from (`codeigniter54900_db`.`company_members` `m` join `codeigniter54900_db`.`companies` `c` on(((`c`.`id` = `m`.`company_id`) and (`c`.`deleted_at` is null)))) where ((`m`.`user_manager_id` = `um`.`id`) and (`m`.`status` = 'active') and (`m`.`deleted_at` is null) and (`m`.`company_id` = `cmx`.`company_id`))) AS `companies_count`,(select left(group_concat(`c`.`name` order by `c`.`name` ASC separator ', '),500) from (`codeigniter54900_db`.`company_members` `m` join `codeigniter54900_db`.`companies` `c` on(((`c`.`id` = `m`.`company_id`) and (`c`.`deleted_at` is null)))) where ((`m`.`user_manager_id` = `um`.`id`) and (`m`.`status` = 'active') and (`m`.`deleted_at` is null) and (`m`.`company_id` = `cmx`.`company_id`))) AS `companies_names`,`um`.`created_at` AS `created_at`,`um`.`updated_at` AS `updated_at`,`um`.`deleted_at` AS `deleted_at` from ((`codeigniter54900_db`.`user_manager` `um` join `codeigniter54900_db`.`company_members` `cmx` on(((`cmx`.`user_manager_id` = `um`.`id`) and (`cmx`.`status` = 'active') and (`cmx`.`deleted_at` is null)))) left join `codeigniter54900_db`.`user_profiles` `uc` on(((`uc`.`user_manager_id` = `um`.`id`) and (`uc`.`deleted_at` is null))));
